export type SdkProvider = "codex" | "anthropic";
export type SdkAuthAction = "login" | "status" | "logout";

export interface SdkAuthInvocation {
  command: string;
  args: string[];
}

/**
 * Resolve the official local authentication command for an SDK provider.
 *
 * Both SDKs deliberately reuse credentials owned by their official CLI. Twyne
 * never reads, copies, logs, or persists the access/refresh tokens itself.
 */
export function sdkAuthInvocation(
  provider: SdkProvider,
  action: SdkAuthAction,
): SdkAuthInvocation {
  if (provider === "codex") {
    if (action === "login") return { command: "codex", args: ["login"] };
    if (action === "status")
      return { command: "codex", args: ["login", "status"] };
    return { command: "codex", args: ["logout"] };
  }

  if (action === "login") return { command: "ant", args: ["auth", "login"] };
  if (action === "status")
    return { command: "ant", args: ["auth", "status"] };
  return { command: "ant", args: ["auth", "logout"] };
}

export async function runSdkAuthCommand(
  provider: SdkProvider,
  action: SdkAuthAction,
  env: NodeJS.ProcessEnv = process.env,
): Promise<void> {
  const invocation = sdkAuthInvocation(provider, action);
  await new Promise<void>((resolve, reject) => {
    const child = spawn(invocation.command, invocation.args, {
      env,
      shell: false,
      stdio: "inherit",
    });
    child.once("error", (error: NodeJS.ErrnoException) => {
      if (error.code === "ENOENT") {
        reject(
          new Error(
            `${invocation.command} is not installed. Install the official ${
              provider === "codex" ? "Codex CLI" : "Anthropic CLI"
            } and try again.`,
          ),
        );
        return;
      }
      reject(error);
    });
    child.once("exit", (code, signal) => {
      if (code === 0) return resolve();
      reject(
        new Error(
          `${provider} ${action} ${
            signal ? `was interrupted by ${signal}` : `exited with code ${code}`
          }.`,
        ),
      );
    });
  });
}
import type Anthropic from "@anthropic-ai/sdk";

export interface AnthropicRunOptions {
  model?: string;
  system?: string;
  maxTokens?: number;
  /** Selects a profile created by `ant auth login --profile NAME`. */
  profile?: string;
}

export interface AnthropicRunResult {
  finalResponse: string;
  model: string;
  stopReason: string | null;
  usage: unknown;
}

export function buildAnthropicClientOptions(
  options: Pick<AnthropicRunOptions, "profile">,
): { profile?: string } {
  return options.profile?.trim() ? { profile: options.profile.trim() } : {};
}

export function anthropicText(
  content: Array<{ type: string; text?: string }>,
): string {
  return content
    .filter(
      (block): block is { type: "text"; text: string } =>
        block.type === "text" && typeof block.text === "string",
    )
    .map((block) => block.text)
    .join("");
}

/**
 * Run one Messages API turn through the official Anthropic SDK.
 *
 * With no API-key environment variable, the SDK resolves the active profile
 * written by `ant auth login` and refreshes its OAuth credential itself.
 */
export async function runAnthropicTask(
  prompt: string,
  options: AnthropicRunOptions = {},
): Promise<AnthropicRunResult> {
  const { default: AnthropicClient } = await import("@anthropic-ai/sdk");
  const client = new AnthropicClient(buildAnthropicClientOptions(options));
  const model = options.model ?? "claude-sonnet-4-6";
  const message = await client.messages.create({
    model,
    max_tokens: options.maxTokens ?? 4096,
    ...(options.system ? { system: options.system } : {}),
    messages: [{ role: "user", content: prompt }],
  });
  return {
    finalResponse: anthropicText(
      message.content as Array<{ type: string; text?: string }>,
    ),
    model: message.model,
    stopReason: message.stop_reason,
    usage: message.usage,
  };
}

